<html lang="en">
<head>
<meta charset="UTF-8">
<title>CHIP-8 Emulator</title>
<style>
body{margin:0;background:#15171c;color:#dde;font-family:system-ui,sans-serif;display:flex;justify-content:center}
.wrap{display:flex;gap:20px;padding:20px;flex-wrap:wrap;justify-content:center}
